<?php
declare(strict_types=1);require dirname(__DIR__).'/app/bootstrap.php';$user=require_permission('clinical.write');\App\Core\Tenant::enforceActive((int)$user['tenant_id']);$id=(int)($_GET['id']??$_POST['id']??0);$st=db()->prepare("SELECT * FROM patients WHERE id=:id AND tenant_id=:t");$st->execute(['id'=>$id,'t'=>$user['tenant_id']]);$p=$st->fetch();if(!$p||!\App\Core\Rbac::canViewPatientClinical($user,$p)){http_response_code(403);require APP_ROOT.'/app/views/403.php';exit;}if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$title=trim($_POST['title']??'');if($title!==''){$st=db()->prepare("INSERT INTO therapeutic_tasks(tenant_id,patient_id,professional_id,title,instructions,due_date,status,created_at,updated_at)VALUES(:t,:p,:u,:title,:i,:d,'open',NOW(),NOW())");$st->execute(['t'=>$user['tenant_id'],'p'=>$id,'u'=>$user['id'],'title'=>$title,'i'=>trim($_POST['instructions']??'')?:null,'d'=>($_POST['due_date']??'')?:null]);audit('clinical.task_create','patient',$id,[]);flash('success','Tarefa enviada ao portal.');redirect('patients/view.php?id='.$id);}}layout('Nova tarefa',function()use($p){?><div class="page-head"><div><span class="eyebrow">Entre sessões</span><h1>Nova tarefa terapêutica</h1><p data-private><?=e($p['name'])?></p></div></div><form method="post" class="card form-grid"><?=csrf_field()?><input type="hidden" name="id" value="<?=$p['id']?>"><div class="field"><label>Título</label><input name="title" required></div><div class="field"><label>Instruções</label><textarea name="instructions"></textarea></div><div class="field"><label>Prazo</label><input type="date" name="due_date"></div><button class="button">Publicar no portal</button></form><?php },['active'=>'patients']);
